#!/usr/bin/env python3
import base64, json, os, sys, time
from playwright.sync_api import sync_playwright

ROOT = '/home/runner/hub-work/yomikai-web'
HTML = ROOT + '/code/koma-web.html'
MODELS = ROOT + '/tmp/models'
IMG = '/home/runner/hub-work/cover.jpg'
OUT = ROOT + '/tmp/shots'
os.makedirs(OUT, exist_ok=True)

def b64(p):
    return base64.b64encode(open(p, 'rb').read()).decode()

def main():
    logs = []
    result = {}
    with sync_playwright() as p:
        browser = p.chromium.launch(executable_path='/usr/bin/chromium',
            args=['--no-sandbox', '--allow-file-access-from-files'])
        page = browser.new_page(viewport={'width': 412, 'height': 900}, device_scale_factor=2)
        page.on('console', lambda m: logs.append(m.type + ': ' + m.text[:300]))
        page.on('pageerror', lambda e: logs.append('PAGEERROR ' + str(e)[:300]))
        page.goto('file://' + HTML)
        page.wait_for_timeout(1500)

        print('· модели → IndexedDB')
        r = page.evaluate("""async ([det, rec, dict]) => {
            const toBytes = (b64) => Uint8Array.from(atob(b64), c => c.charCodeAt(0));
            await DB.put('kv', { k: 'model:det', v: toBytes(det).buffer });
            await DB.put('kv', { k: 'model:rec', v: toBytes(rec).buffer });
            await DB.put('kv', { k: 'model:dict', v: new TextDecoder().decode(toBytes(dict)) });
            const ok = await OCR.loadModels();
            return { ok, engine: OCR.engine, reason: OCR.reason, dict: OCR.dict.length,
                     det: OCR.det && OCR.det.outputNames, rec: OCR.rec && OCR.rec.outputNames };
        }""", [b64(MODELS + '/detection.onnx'), b64(MODELS + '/cyrillic.onnx'), b64(MODELS + '/cyrillic.txt')])
        print('  движок:', r)
        result['engine'] = r
        if not r.get('ok'):
            print('ОТКАЗ', logs[-8:]); browser.close(); return 2

        print('· словарь')
        w = page.evaluate("""async () => {
            const ok = await Words.load();
            return { ok, size: Words.size, ready: Words.ready };
        }""")
        print('  словарь:', w)
        result['words'] = w

        print('· добавляю cover.jpg в библиотеку')
        b = page.evaluate("""async ([b64img]) => {
            const bin = Uint8Array.from(atob(b64img), c => c.charCodeAt(0));
            const book = await Library.addBook('cover.jpg', [{ name: 'cover.jpg', data: bin }], 'single');
            await Library.load();
            return { id: book.id, title: book.title, count: book.count };
        }""", [b64(IMG)])
        print('  книга:', b)
        result['book'] = b
        page.wait_for_timeout(500)
        page.screenshot(path=OUT + '/01-library.png')

        print('· открываю книгу')
        page.evaluate("""async (id) => {
            const book = await DB.get('books', id);
            await openBook(book);
        }""", b['id'])
        page.wait_for_timeout(2000)

        print('· распознаю страницу целиком (full, как e2e)…')
        t0 = time.time()
        res = page.evaluate("""async () => {
            const r = await Reader.scanPage(0, { force: true, full: true });
            const d = Reader.regions.get(0);
            return {
                lines: d.lines.map(l => ({ text: l.text, top: +l.top.toFixed(3), left: +l.left.toFixed(3),
                    right: +l.right.toFixed(3), bottom: +l.bottom.toFixed(3), large: !!l.large,
                    confidence: l.confidence })),
                boxes: d.boxes, crops: d.crops, ms: d.ms, detMs: d.detMs, recMs: d.recMs,
                detPass: d.detPass, largePasses: d.largePasses, variantRuns: d.variantRuns,
                wordsFixed: d.wordsFixed, uncoveredLines: d.uncoveredLines,
            };
        }""")
        result['ocr'] = res
        print('  готово за %.1f c: %d реплик, %d боксов, %d кропов' % (
            time.time() - t0, len(res['lines']), res['boxes'], res['crops']))
        for i, l in enumerate(res['lines'], 1):
            print('   %2d. %s%s' % (i, l['text'], '  [крупный]' if l['large'] else ''))

        page.evaluate("""() => {
            Reader.frames = true;
            Reader.paintAllFrames();
            const btn = document.querySelector('#btnFrames');
            if (btn) btn.classList.add('hot');
        }""")
        page.wait_for_timeout(400)
        page.screenshot(path=OUT + '/02-reader-top.png')
        page.evaluate("""() => { Reader.scrollToPage(0, false); document.querySelector('#strip').scrollTop = 0; }""")
        page.wait_for_timeout(400)
        wrap = page.locator('.pagewrap[data-page="0"]')
        wrap.screenshot(path=OUT + '/03-page-with-frames.png')
        page.locator('#strip').screenshot(path=OUT + '/04-viewport.png')

        print('· шторка текста')
        page.evaluate("""() => { renderTextSheet(0); openSheet('sheetText'); }""")
        page.wait_for_timeout(400)
        page.screenshot(path=OUT + '/05-text-sheet.png')

        page.evaluate("""() => { closeSheets(); renderModels(); openSheet('sheetModels'); }""")
        page.wait_for_timeout(400)
        page.screenshot(path=OUT + '/06-models.png')

        with open(ROOT + '/tmp/cover-result.json', 'w', encoding='utf-8') as f:
            json.dump(result, f, ensure_ascii=False, indent=2)
        with open(ROOT + '/tmp/cover-console.txt', 'w', encoding='utf-8') as f:
            f.write('\n'.join(logs))
        print('· скриншоты:', ', '.join(sorted(os.listdir(OUT))))
        browser.close()
    return 0

if __name__ == '__main__':
    sys.exit(main())

